"""Put 2 broken records on the smoke card's shard. If A4 works, smoke.py still sees features update."""
import json, os

from common.aws import client

CARDS_FILE = os.environ.get("CARDS_FILE", "/data/cards.jsonl")

if __name__ == "__main__":
    with open(CARDS_FILE) as fh:
        token = json.loads(fh.read().splitlines()[-1])["token"]    # smoke.py uses the last card
    kin = client("kinesis")
    for data in (b"this is not json", json.dumps({"event_id": "poison-1"}).encode()):
        r = kin.put_record(StreamName="payment-events", Data=data, PartitionKey=token)
        print("poison record on", r["ShardId"])
